INA_LANDSCAPE_16_9.jpg', 'width': 1136, 'height': 639, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/cda/bd5b9511-a109-42be-bd5e-df223e1e0cda_TABLET_LANDSCAPE_16_9.jpg', 'width': 1024, 'height': 576, 'fallback': False}], 'classifications': [{'primary': True, 'segment': {'id': 'KZFzniwnSyZfZ7v7nJ', 'name': 'Music'}, 'genre': {'id': 'KnvZfZ7vAeA', 'name': 'Rock'}, 'subGenre': {'id': 'KZazBEonSMnZfZ7v6dt', 'name': 'Alternative Rock'}, 'type': {'id': 'KZAyXgnZfZ7v7nI', 'name': 'Undefined'}, 'subType': {'id': 'KZFzBErXgnZfZ7v7lJ', 'name': 'Undefined'}, 'family': False}], 'upcomingEvents': {'universe': 3, 'mfx-es': 4, 'ticketmaster': 14, '_total': 21, '_filtered': 0}, '_links': {'self': {'href': '/discovery/v2/attractions/K8vZ9171F50?locale=en-us'}}}]}

{'venues': [{'name': 'Arts Club Liverpool - Loft', 'type': 'venue', 'id': 'KovZ9177aNf', 'test': False, 'url': 'https://www.ticketmaster.co.uk/arts-club-liverpool-loft-tickets-liverpool/venue/255726', 'locale': 'en-us', 'distance': 0.49, 'units': 'MILES', 'postalCode': 'L1 4BH', 'timezone': 'Europe/London', 'city': {'name': 'Liverpool'}, 'country': {'name': 'Great Britain', 'countryCode': 'GB'}, 'address': {'line1': '90 Seel Street'}, 'location': {'longitude': '-2.97780543', 'latitude': '53.40156251'}, 'markets': [{'name': 'All of United Kingdom', 'id': '201'}, {'name': 'North and North East', 'id': '206'}], 'dmas': [{'id': 601}, {'id': 606}], 'boxOfficeInfo': {'phoneNumberDetail': 'Box Office and ticketing service Ticketmaster is our official booking partner, selling tickets for all Academy Music Group venues in the UK. You can book online or call them on 0844 477 2000 (calls cost 7p per minute, plus your network charge).', 'openHoursDetail': "You can also book in person at O2 Academy Liverpool on Hotham Street. Our terms and conditions of entry are here. Box Office Hours Box office times O2 Academy Liverpool is open from 10.30am to 5.30pm, Monday to Saturday and sells tickets for all Arts Club Liverpool shows and events. Please be aware that our Arts Club Liverpool box office is only open on show days for all customer collections and purchases. Opening times will be different on bank holidays, so do check. We'll have opening times and curfew times if they're out of the ordinary for seasoned gig goers (7pm to 11pm) on the event page of this website and on our social channels, too. All timings are subject to change, so check before you travel. Box Office Collection Accepted Please be aware that our Arts Club Liverpool box office is only open on show days for all customer collections and purchases. Box Office Payment We accept all cards including American Express, as well as Apple Pay and Android Pay. Accessible Seating Unfortunately, there is no wheelchair access available to The Loft. Please check where the advertised performance will take place via our website or the website of any of our authorised ticket retailers before continuing with your purchase. If you are unable to access the website please call us for further details on 0151 559 3773."}, 'parkingDetail': "There are parking facilities at Q Park on Hannover Street, right next to the Liverpool One shopping centre. The post code for your sat nav is L1 4AF. There's also National Car Parks on Seel Street, use sat nav postcode L1 4AZ and you'll find several privately owned parking options around our venue. Disabled parking and by car Our venue doesn't have its our own parking facilities, Back Colquitt Street is adjacent to the venue with single yellow lines and right opposite us you'll see a loading bay as a drop off point. If you are a Blue Badge holder and want to find out more details, just click here. Public Transportation By bus We're right by the corner crossing of Seel Street and Berry Street. The nearest bus stop is on Berry Street and our local buses are numbers 82, 82B and 82D that run between Speke and the city centre.", 'accessibleSeatingDetail': 'We advise patrons to contact the venue via email evac.boxoffice@mamaco.com or telephone on 0151 559 3773 check availability of disabled and specific access seating before purchasing a ticket through any of our authorised ticket agents. Due to Licensing and Health & Safety Assessments, we regret the number of wheelchairs that we can admit to the main auditorium is limited and we must treat all patrons on a first come first served basis. Once the venue has confirmed availability you can purchase a ticket through our event listings page or by phoning 0844 847 2472 and the venue will arrange for a free personal assistant ticket to be available for patrons who are registered disabled. A photocopy/scan of one of the following official documents (dated within the past 12 months) will enable you to qualify for a free personal assistant ticket. Please do not send the original copy. Front page of DLA letter Front page of Attendance Allowance letter Evidence that registered severely sight impaired Recognised Assistance Dog ID card Please note that a ticket will not be sent out to your PA prior to the event. They will be available for collection at the venue Box Office when you arrive. On the evening of the event, we advise disabled customers and those with specific access requirements to arrive at the venue 15 minutes prior to the doors opening, accompanied, where required and approved in advance by a personal assistant over 18 years of age who will be admitted free of charge. The free personal assistant ticket is available to customers that are registered disabled (see above for details). The paid for ticket needs to be booked in advance.', 'generalInfo': {'generalRule': "If we've missed anything, it will be in the venues FAQs ourhttps://academymusicgroup.com/artsclubliverpool/faq No under 14s please, but feel free to contact us if you're unsure and avoid disappointment. Anyone under 16 (but over 14), you'll need to attend with an adult (18+) but check the event details. If it says 14+, 16+, 18+, 21+… be sure to check before you book and remember to carry proof of age if you need it.", 'childRule': "It's always best to check the age restrictions for each event in advance as they vary from show to show. A few obvious ones:"}, 'upcomingEvents': {'universe': 1, 'ticketmaster': 3, '_total': 4, '_filtered': 0}, 'ada': {'adaPhones': '000000000000
', 'adaCustomCopy': 'For further information about accessibility and tickets, please check the venue site here (link out to https://www.arts-club-liverpool.com/accessibility/)

', 'adaHours': 'https://www.arts-club-liverpool.com/accessibility/ (copy to browser).'}, '_links': {'self': {'href': '/discovery/v2/venues/KovZ9177aNf?locale=en-us'}}}], 'attractions': [{'name': 'Girl In The Year Above', 'type': 'attraction', 'id': 'K8vZ917rmJ7', 'test': False, 'url': 'https://www.ticketmaster.com/girl-in-the-year-above-tickets/artist/4001854', 'locale': 'en-us', 'externalLinks': {'youtube': [{'url': 'https://www.youtube.com/@Girlintheyearabove'}], 'instagram': [{'url': 'https://www.instagram.com/girlintheyearabove/'}]}, 'images': [{'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_TABLET_LANDSCAPE_16_9.jpg', 'width': 1024, 'height': 576, 'fallback': False}, {'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_SOURCE', 'width': 3727, 'height': 4897, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_RETINA_LANDSCAPE_16_9.jpg', 'width': 1136, 'height': 639, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_RETINA_PORTRAIT_16_9.jpg', 'width': 640, 'height': 360, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_EVENT_DETAIL_PAGE_16_9.jpg', 'width': 205, 'height': 115, 'fallback': False}, {'ratio': '4_3', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_CUSTOM.jpg', 'width': 305, 'height': 225, 'fallback': False}, {'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_RETINA_PORTRAIT_3_2.jpg', 'width': 640, 'height': 427, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_RECOMENDATION_16_9.jpg', 'width': 100, 'height': 56, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_TABLET_LANDSCAPE_LARGE_16_9.jpg', 'width': 2048, 'height': 1152, 'fallback': False}, {'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_ARTIST_PAGE_3_2.jpg', 'width': 305, 'height': 203, 'fallback': False}, {'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/10f/69ae7e73-4797-48c0-8779-97b582d7710f_TABLET_LANDSCAPE_3_2.jpg', 'width': 1024, 'height': 683, 'fallback': False}], 'classifications': [{'primary': True, 'segment': {'id': 'KZFzniwnSyZfZ7v7nJ', 'name': 'Music'}, 'genre': {'id': 'KnvZfZ7vAev', 'name': 'Pop'}, 'subGenre': {'id': 'KZazBEonSMnZfZ7vkJ1', 'name': 'Celtic Pop'}, 'type': {'id': 'KZAyXgnZfZ7v7l1', 'name': 'Group'}, 'subType': {'id': 'KZFzBErXgnZfZ7vA71', 'name': 'Band'}, 'family': False}], 'upcomingEvents': {'universe': 1, 'ticketmaster': 12, '_total': 13, '_filtered': 0}, '_links': {'self': {'href': '/discovery/v2/attractions/K8vZ917rmJ7?locale=en-us'}}}, {'name': 'RAGEFLOWER', 'type': 'attraction', 'id': 'K8vZ917Oc6f', 'test': False, 'url': 'https://www.ticketmaster.com/rageflower-tickets/artist/4524914', 'locale': 'en-us', 'externalLinks': {'spotify': [{'url': 'https://open.spotify.com/artist/0jHAwb83XpyQCuKAsrNaNG'}], 'instagram': [{'url': 'https://www.instagram.com/rage_flower/'}]}, 'images': [{'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/cf5/e01c20f2-1dd6-4241-97b7-097c67875cf5_SOURCE', 'width': 6000, 'height': 4000, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/cf5/e01c20f2-1dd6-4241-97b7-097c67875cf5_TABLET_LANDSCAPE_16_9.jpg', 'width': 1024, 'height': 576, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/cf5/e01c20f2-1dd6-4241-97b7-097c67875cf5_RETINA_LANDSCAPE_16_9.jpg', 'width': 1136, 'height': 639, 'fallback': False}, {'ratio': '16_9', 'url': 'https://s1.ticketm.net/dam/a/cf5/e01c20f2-1dd6-4241-97b7-097c67875cf5_TABLET_LANDSCAPE_LARGE_16_9.jpg', 'width': 2048, 'height': 1152, 'fallback': False}, {'ratio': '3_2', 'url': 'https://s1.ticketm.net/dam/a/cf5